case "cmd_copyDecryptedTo": {
  let showDecrypt = numSelectedMessages > 1;
  if (numSelectedMessages == 1 && !isDummyMessage) {
    const msgURI = gDBView.URIForFirstSelectedMessage;
    if (msgURI) {
      showDecrypt = gEncryptedURIService.isEncrypted(msgURI);
    }
  }
  return showDecrypt;
}
